import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 smem[];
.visible .entry convtrans2d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .s32 N,
    .param .s32 Cin,
    .param .s32 Cout,
    .param .s32 H,
    .param .s32 W,
    .param .s32 kH,
    .param .s32 kW,
    .param .s32 stride_h,
    .param .s32 stride_w,
    .param .s32 pad_h,
    .param .s32 pad_w,
    .param .s32 dil_h,
    .param .s32 dil_w,
    .param .s32 groups,
    .param .s32 Ho,
    .param .s32 Wo,
    .param .s32 has_bias
)
{
    .reg .pred  %p<28>;
    .reg .b64   %rd<40>;
    // Float registers
    .reg .f32   %fAcc, %f1, %f2, %f3, %fBias;
    // 32-bit integer registers (signed)
    .reg .s32 %rN, %rCin, %rCout, %rH, %rW, %rKH, %rKW, %rStrideH, %rStrideW, %rPadH, %rPadW, %rDilH, %rDilW, %rGroups, %rHo, %rWo, %rHasBias;
    .reg .s32 %rTid, %rTotal, %rWoIdx, %rQ0, %rHoIdx, %rQ1, %rCoIdx, %rNIdx, %rCoutPerG, %rCinPerG, %rG, %rTmp0, %rCoRel, %rCiStart, %rCiEnd, %rCi, %rKh, %rTmp1, %rTh, %rQh, %rTmp2, %rRemH, %rKw, %rTmp3, %rTw, %rQw, %rTmp4, %rRemW, %rTmp5, %rXIndex, %rTmp6, %rWIndex, %rTmp7, %rYIndex;
    // Additional integer registers
    .reg .s32 %rBS, %rBE, %rTotMinus1, %rQB0, %rQB1, %rQE0, %rQE1, %rCoStartU, %rCoEndU, %rGUniform, %rCoRelU, %rLoadKw, %rBaseX, %rBaseW, %rBaseWU, %rDilWm;
    // Async pipeline helpers
    .reg .s32 %rBufSel, %rNextKh, %rKhEndM1, %rHasNext, %rLoadKwN;
    // Warp-level helpers
    .reg .u32 %tid_x_u32, %ntid_x_u32, %ctaid_x_u32, %lane_u32, %warpId_u32, %bias_bits, %bias_bits_bcast;
    .reg .s32 %tid_x_s32, %ntid_x_s32, %ctaid_x_s32, %rLane, %rWarp;
    .reg .s32 %rWTidStart, %rWTidEnd, %rCoStartW, %rCoEndW, %rGUniformW, %rCoRelW, %rLoadKwW, %rWOffset;
    .reg .s32 %rWQ0, %rWQ1, %rWQ0e, %rWQ1e, %rWoTmp, %rHoTmp, %rWoTmpe, %rHoTmpe;
    // Load parameters
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [y_ptr];
    ld.param.s32 %rN,       [N];
    ld.param.s32 %rCin,     [Cin];
    ld.param.s32 %rCout,    [Cout];
    ld.param.s32 %rH,       [H];
    ld.param.s32 %rW,       [W];
    ld.param.s32 %rKH,      [kH];
    ld.param.s32 %rKW,      [kW];
    ld.param.s32 %rStrideH, [stride_h];
    ld.param.s32 %rStrideW, [stride_w];
    ld.param.s32 %rPadH,    [pad_h];
    ld.param.s32 %rPadW,    [pad_w];
    ld.param.s32 %rDilH,    [dil_h];
    ld.param.s32 %rDilW,    [dil_w];
    ld.param.s32 %rGroups,  [groups];
    ld.param.s32 %rHo,      [Ho];
    ld.param.s32 %rWo,      [Wo];
    ld.param.s32 %rHasBias, [has_bias];
    // Compute global linear thread id
    mov.u32     %tid_x_u32,   %tid.x;
    mov.u32     %ntid_x_u32,  %ntid.x;
    mov.u32     %ctaid_x_u32, %ctaid.x;
    cvt.s32.u32 %tid_x_s32,   %tid_x_u32;
    cvt.s32.u32 %ntid_x_s32,  %ntid_x_u32;
    cvt.s32.u32 %ctaid_x_s32, %ctaid_x_u32;
    mad.lo.s32  %rTid, %ctaid_x_s32, %ntid_x_s32, %tid_x_s32;    // rTid = blockIdx.x * blockDim.x + threadIdx.x
    // total_elems = N * Cout * Ho * Wo
    mul.lo.s32 %rTmp0, %rN, %rCout;
    mul.lo.s32 %rTmp1, %rTmp0, %rHo;
    mul.lo.s32 %rTotal, %rTmp1, %rWo;
    // Compute block start/end and check if co is uniform across this block
    mul.lo.s32 %rBS, %ctaid_x_s32, %ntid_x_s32;
    add.s32 %rBE, %rBS, %ntid_x_s32;
    add.s32 %rBE, %rBE, -1;
    add.s32 %rTotMinus1, %rTotal, -1;
    setp.gt.s32 %p0, %rBE, %rTotMinus1;
    @%p0 mov.s32 %rBE, %rTotMinus1;
    // Decode co for block start
    rem.s32 %rWoIdx, %rBS, %rWo;
    div.s32 %rQB0, %rBS, %rWo;
    rem.s32 %rHoIdx, %rQB0, %rHo;
    div.s32 %rQB1, %rQB0, %rHo;
    rem.s32 %rCoStartU, %rQB1, %rCout;
    // Decode co for block end
    rem.s32 %rTmp0, %rBE, %rWo;
    div.s32 %rQE0, %rBE, %rWo;
    rem.s32 %rTmp1, %rQE0, %rHo;
    div.s32 %rQE1, %rQE0, %rHo;
    rem.s32 %rCoEndU, %rQE1, %rCout;
    setp.eq.s32 %p11, %rCoStartU, %rCoEndU; // p11 == uniform co across block
    // Compute warp id/lane id
    and.b32 %lane_u32, %tid_x_u32, 31;
    shr.u32 %warpId_u32, %tid_x_u32, 5;
    cvt.s32.u32 %rLane, %lane_u32;
    cvt.s32.u32 %rWarp, %warpId_u32;
    // Compute warp start/end, and check if co is uniform across this warp
    shl.b32 %rTmp0, %rWarp, 5;                // rWarp*32
    add.s32 %rWTidStart, %rBS, %rTmp0;
    add.s32 %rWTidEnd, %rWTidStart, 31;
    setp.gt.s32 %p12, %rWTidEnd, %rTotMinus1;
    @%p12 mov.s32 %rWTidEnd, %rTotMinus1;
    // co for warp start
    rem.s32 %rWoTmp, %rWTidStart, %rWo;
    div.s32 %rWQ0, %rWTidStart, %rWo;
    rem.s32 %rHoTmp, %rWQ0, %rHo;
    div.s32 %rWQ1, %rWQ0, %rHo;
    rem.s32 %rCoStartW, %rWQ1, %rCout;
    // co for warp end
    rem.s32 %rWoTmpe, %rWTidEnd, %rWo;
    div.s32 %rWQ0e, %rWTidEnd, %rWo;
    rem.s32 %rHoTmpe, %rWQ0e, %rHo;
    div.s32 %rWQ1e, %rWQ0e, %rHo;
    rem.s32 %rCoEndW, %rWQ1e, %rCout;
    setp.eq.s32 %p13, %rCoStartW, %rCoEndW; // p13 == uniform co across warp
    // Preload bias once per warp/block when possible to reduce redundant global loads
    mov.f32 %fBias, 0f00000000;
    setp.eq.s32 %p16, %rHasBias, 0;
    @%p16 bra BIAS_PRELOAD_DONE;
    @%p11 bra BIAS_LOAD_BLOCK;
    @%p13 bra BIAS_LOAD_WARP;
    bra BIAS_PRELOAD_DONE;
BIAS_LOAD_BLOCK:
    // Block-uniform co: lane 0 of each warp loads bias for rCoStartU and broadcasts within the warp
    setp.eq.s32 %p23, %rLane, 0;
    @!%p23 bra BIAS_B_SKIP;
    mul.wide.s32 %rd9, %rCoStartU, 4;
    add.s64 %rd10, %rd3, %rd9;
    ld.global.f32 %fBias, [%rd10];
BIAS_B_SKIP:
    mov.b32 %bias_bits, %fBias;
    shfl.sync.idx.b32 %bias_bits_bcast, %bias_bits, 0, 0x1f, 0xffffffff;
    mov.b32 %fBias, %bias_bits_bcast;
    bra BIAS_PRELOAD_DONE;
BIAS_LOAD_WARP:
    // Warp-uniform co: lane 0 loads bias for rCoStartW and broadcasts within the warp
    setp.eq.s32 %p23, %rLane, 0;
    @!%p23 bra BIAS_W_SKIP;
    mul.wide.s32 %rd9, %rCoStartW, 4;
    add.s64 %rd10, %rd3, %rd9;
    ld.global.f32 %fBias, [%rd10];
BIAS_W_SKIP:
    mov.b32 %bias_bits, %fBias;
    shfl.sync.idx.b32 %bias_bits_bcast, %bias_bits, 0, 0x1f, 0xffffffff;
    mov.b32 %fBias, %bias_bits_bcast;
BIAS_PRELOAD_DONE:
    // Bounds check for this thread
    setp.ge.s32 %p1, %rTid, %rTotal;
    @%p1 bra EXIT;
    // Decode indices from rTid: [n, co, ho, wo] with order Wo->Ho->Cout->N
    // wo = rTid % Wo
    rem.s32 %rWoIdx, %rTid, %rWo;
    // q = rTid / Wo
    div.s32 %rQ0, %rTid, %rWo;
    // ho = q % Ho
    rem.s32 %rHoIdx, %rQ0, %rHo;
    // q = q / Ho
    div.s32 %rQ1, %rQ0, %rHo;
    // co = q % Cout
    rem.s32 %rCoIdx, %rQ1, %rCout;
    // n = q / Cout
    div.s32 %rNIdx, %rQ1, %rCout;
    // Group computations
    div.s32 %rCoutPerG, %rCout, %rGroups;
    div.s32 %rCinPerG, %rCin, %rGroups;
    // g = co / CoutPerG
    div.s32 %rG, %rCoIdx, %rCoutPerG;
    // co_rel = co - g*CoutPerG
    mul.lo.s32 %rTmp0, %rG, %rCoutPerG;
    sub.s32 %rCoRel, %rCoIdx, %rTmp0;
    // ci_start = g*CinPerG; ci_end = ci_start + CinPerG
    mul.lo.s32 %rCiStart, %rG, %rCinPerG;
    add.s32 %rCiEnd, %rCiStart, %rCinPerG;
    // Accumulator
    mov.f32 %fAcc, 0f00000000;
    // Prepare uniform co_rel for shared-memory path
    // rGUniform = coStartU / CoutPerG; rCoRelU = coStartU - rGUniform*CoutPerG
    div.s32 %rGUniform, %rCoStartU, %rCoutPerG;
    mul.lo.s32 %rTmp0, %rGUniform, %rCoutPerG;
    sub.s32 %rCoRelU, %rCoStartU, %rTmp0;
    // Prepare uniform co_rel for warp-level path
    div.s32 %rGUniformW, %rCoStartW, %rCoutPerG;
    mul.lo.s32 %rTmp0, %rGUniformW, %rCoutPerG;
    sub.s32 %rCoRelW, %rCoStartW, %rTmp0;
    // Start of loops: choose shared-memory path if co is uniform across block, else per-warp if uniform within warp
    mov.s32 %rCi, %rCiStart;
    @%p11 bra U_CI_LOOP; // if uniform co across block, use block shared-memory staging
    @%p13 bra W_CI_LOOP; // else if uniform co across warp, use per-warp shared-memory staging
CI_LOOP:
    setp.ge.s32 %p2, %rCi, %rCiEnd;
    @%p2 bra AFTER_CI;
    // kh loop
    mov.s32 %rKh, 0;
KH_LOOP:
    setp.ge.s32 %p3, %rKh, %rKH;
    @%p3 bra NEXT_CI;
    // t_h = ho + pad_h - kh * dil_h
    mul.lo.s32 %rTmp1, %rKh, %rDilH;
    add.s32 %rTh, %rHoIdx, %rPadH;
    sub.s32 %rTh, %rTh, %rTmp1;
    // qh = t_h / stride_h; remh = t_h - qh*stride_h
    div.s32 %rQh, %rTh, %rStrideH;
    mul.lo.s32 %rTmp2, %rQh, %rStrideH;
    sub.s32 %rRemH, %rTh, %rTmp2;
    setp.ne.s32 %p4, %rRemH, 0;
    @%p4 bra NEXT_KH;
    setp.lt.s32 %p5, %rQh, 0;
    @%p5 bra NEXT_KH;
    setp.ge.s32 %p6, %rQh, %rH;
    @%p6 bra NEXT_KH;
    // Hoist base indices for KW loop
    // baseX = (((n*Cin + ci)*H + qh)*W)
    mul.lo.s32 %rBaseX, %rNIdx, %rCin;
    add.s32 %rBaseX, %rBaseX, %rCi;
    mul.lo.s32 %rBaseX, %rBaseX, %rH;
    add.s32 %rBaseX, %rBaseX, %rQh;
    mul.lo.s32 %rBaseX, %rBaseX, %rW;
    // baseW = ((((ci)*CoutPerG + co_rel)*kH + kh)*kW)
    mul.lo.s32 %rBaseW, %rCi, %rCoutPerG;
    add.s32 %rBaseW, %rBaseW, %rCoRel;
    mul.lo.s32 %rBaseW, %rBaseW, %rKH;
    add.s32 %rBaseW, %rBaseW, %rKh;
    mul.lo.s32 %rBaseW, %rBaseW, %rKW;
    // kw loop
    // kw loop (unrolled by 4)
    mov.s32 %rKw, 0;
    // Precompute Tw0 and modular step for stride check
    add.s32 %rTw, %rWoIdx, %rPadW;
    rem.s32 %rDilWm, %rDilW, %rStrideW;
    rem.s32 %rRemW, %rTw, %rStrideW;
    setp.lt.s32 %p17, %rRemW, 0;
    @%p17 add.s32 %rRemW, %rRemW, %rStrideW;
KW_LOOP:
    setp.ge.s32 %p7, %rKw, %rKW;
    @%p7 bra NEXT_KH;
    // Iteration 0
    setp.ne.s32 %p8, %rRemW, 0;
    @%p8 bra KW_STEP1_DONE;
    div.s32 %rQw, %rTw, %rStrideW;
    setp.lt.s32 %p9, %rQw, 0;
    @%p9 bra KW_STEP1_DONE;
    setp.ge.s32 %p10, %rQw, %rW;
    @%p10 bra KW_STEP1_DONE;
    // x_index = baseX + qw
    add.s32 %rXIndex, %rBaseX, %rQw;
    // w_index = baseW + kw
    add.s32 %rWIndex, %rBaseW, %rKw;
    // Load x and w
    mul.wide.s32 %rd5, %rXIndex, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];
    mul.wide.s32 %rd7, %rWIndex, 4;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f2, [%rd8];
    // acc += x * w
    fma.rn.f32 %fAcc, %f1, %f2, %fAcc;
KW_STEP1_DONE:
    // step 0 increment
    add.s32 %rKw, %rKw, 1;
    sub.s32 %rTw, %rTw, %rDilW;
    sub.s32 %rRemW, %rRemW, %rDilWm;
    setp.lt.s32 %p18, %rRemW, 0;
    @%p18 add.s32 %rRemW, %rRemW, %rStrideW;
    // Check for second iteration
    setp.ge.s32 %p19, %rKw, %rKW;
    @%p19 bra KW_LOOP;
    // Iteration 1
    setp.ne.s32 %p20, %rRemW, 0;
    @%p20 bra KW_STEP2_DONE;
    div.s32 %rQw, %rTw, %rStrideW;
    setp.lt.s32 %p21, %rQw, 0;
    @%p21 bra KW_STEP2_DONE;
    setp.ge.s32 %p22, %rQw, %rW;
    @%p22 bra KW_STEP2_DONE;
    add.s32 %rXIndex, %rBaseX, %rQw;
    add.s32 %rWIndex, %rBaseW, %rKw;
    mul.wide.s32 %rd5, %rXIndex, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];
    mul.wide.s32 %rd7, %rWIndex, 4;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f2, [%rd8];
    fma.rn.f32 %fAcc, %f1, %f2, %fAcc;
KW_STEP2_DONE:
    // step 1 increment
    add.s32 %rKw, %rKw, 1;
    sub.s32 %rTw, %rTw, %rDilW;
    sub.s32 %rRemW, %rRemW, %rDilWm;
    setp.lt.s32 %p18, %rRemW, 0;
    @%p18 add.s32 %rRemW, %rRemW, %rStrideW;
    // Check for third iteration
    setp.ge.s32 %p19, %rKw, %rKW;
    @%p19 bra KW_LOOP;
    // Iteration 2
    setp.ne.s32 %p8, %rRemW, 0;
    @%p8 bra KW_STEP3_DONE;
    div.s32 %rQw, %rTw, %rStrideW;
    setp.lt.s32 %p9, %rQw, 0;
    @%p9 bra KW_STEP3_DONE;
    setp.ge.s32 %p10, %rQw, %rW;
    @%p10 bra KW_STEP3_DONE;
    add.s32 %rXIndex, %rBaseX, %rQw;
    add.s32 %rWIndex, %rBaseW, %rKw;
    mul.wide.s32 %rd5, %rXIndex, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];
    mul.wide.s32 %rd7, %rWIndex, 4;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f2, [%rd8];
    fma.rn.f32 %fAcc, %f1, %f2, %fAcc;
KW_STEP3_DONE:
    // step 2 increment
    add.s32 %rKw, %rKw, 1;
    sub.s32 %rTw, %rTw, %rDilW;
    sub.s32 %rRemW, %rRemW, %rDilWm;
    setp.lt.s32 %p18, %rRemW, 0;
    @%p18 add.s32 %rRemW, %rRemW, %rStrideW;
    // Check for fourth iteration
    setp.ge.s32 %p19, %rKw, %rKW;
    @%p19 bra KW_LOOP;
    // Iteration 3
    setp.ne.s32 %p20, %rRemW, 0;
    @%p20 bra KW_STEP4_DONE;
    div.s32 %rQw, %rTw, %rStrideW;
    setp.lt.s32 %p21, %rQw, 0;
    @%p21 bra KW_STEP4_DONE;
    setp.ge.s32 %p22, %rQw, %rW;
    @%p22 bra KW_STEP4_DONE;
    add.s32 %rXIndex, %rBaseX, %rQw;
    add.s32 %rWIndex, %rBaseW, %rKw;
    mul.wide.s32 %rd5, %rXIndex, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];
    mul.wide.s32 %rd7, %rWIndex, 4;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f2, [%rd8];
    fma.rn.f32 %fAcc, %f1, %f2, %fAcc;
KW_STEP4_DONE:
    // step 3 increment
    add.s32 %rKw, %rKw, 1;
    sub.s32 %rTw, %rTw, %rDilW;
    sub.s32 %rRemW, %rRemW, %rDilWm;
    setp.lt.s32 %p18, %rRemW, 0;
    @%p18 add.s32 %rRemW, %rRemW, %rStrideW;
    bra KW_LOOP;
NEXT_KH:
    add.s32 %rKh, %rKh, 1;
    bra KH_LOOP;
NEXT_CI:
    add.s32 %rCi, %rCi, 1;
    bra CI_LOOP;
    // Block-uniform shared-memory path with cp.async double-buffered weight staging
U_CI_LOOP:
    setp.ge.s32 %p2, %rCi, %rCiEnd;
    @%p2 bra AFTER_CI;
    mov.s32 %rKh, 0;
    // precompute bytes per KW
    mul.wide.s32 %rd33, %rKW, 4;            // rd33 = KW * 4
U_KH_LOOP:
    setp.ge.s32 %p3, %rKh, %rKH;
    @%p3 bra U_NEXT_CI;
    // Compute t_h and qh guards
    mul.lo.s32 %rTmp1, %rKh, %rDilH;
    add.s32 %rTh, %rHoIdx, %rPadH;
    sub.s32 %rTh, %rTh, %rTmp1;
    div.s32 %rQh, %rTh, %rStrideH;
    mul.lo.s32 %rTmp2, %rQh, %rStrideH;
    sub.s32 %rRemH, %rTh, %rTmp2;
    // Compute baseWU for current KH (for first-time priming or when computing current buffer base)
    mul.lo.s32 %rBaseWU, %rCi, %rCoutPerG;
    add.s32 %rBaseWU, %rBaseWU, %rCoRelU;
    mul.lo.s32 %rBaseWU, %rBaseWU, %rKH;
    add.s32 %rBaseWU, %rBaseWU, %rKh;
    mul.lo.s32 %rBaseWU, %rBaseWU, %rKW;
    // Setup smem base and buffers
    mov.u64 %rd20, smem;                    // smem base
    // On first KH (rKh==0), issue initial prefetch into buffer 0
    setp.eq.s32 %p24, %rKh, 0;
    @!%p24 bra U_PREFETCH_STARTED;
    // Prime buffer 0
    mov.s32 %rBufSel, 0;
    mov.s32 %rLoadKw, %tid_x_s32;
U_PREFETCH0_LOOP:
    setp.ge.s32 %p14, %rLoadKw, %rKW;
    @%p14 bra U_PREFETCH0_DONE;
    add.s32 %rTmp6, %rBaseWU, %rLoadKw;
    mul.wide.s32 %rd7, %rTmp6, 4;           // src offset bytes
    add.s64 %rd8, %rd2, %rd7;               // src ptr
    mul.wide.s32 %rd21, %rLoadKw, 4;        // dst offset within buf0
    add.s64 %rd22, %rd20, %rd21;            // dst ptr (buf0)
    cp.async.ca.shared.global [%rd22], [%rd8], 4;
    add.s32 %rLoadKw, %rLoadKw, %ntid_x_s32;
    bra U_PREFETCH0_LOOP;
U_PREFETCH0_DONE:
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
U_PREFETCH_STARTED:
    // Decide if next KH exists and start prefetch into opposite buffer
    add.s32 %rNextKh, %rKh, 1;
    add.s32 %rKhEndM1, %rKH, -1;
    setp.le.s32 %p25, %rNextKh, %rKhEndM1;   // next exists if rNextKh <= KH-1
