    .reg .s32 %rBS, %rBE, %rTotMinus1, %rQB0, %rQB1, %rQE0, %rQE1, %rCoStartU, %rCoEndU, %rGUniform, %rCoRelU, %rLoadKw, %rBaseX, %rBaseW, %rBaseWU, %rDilWm, %rKwNext;
