    @!%p23 bra BIAS_B_SKIP;
    mul.wide.s32 %rd9, %rCoStartU, 4;
    add.s64 %rd10, %rd3, %rd9;
    ld.global.f32 %fBias, [%rd10];
BIAS_B_SKIP:
    mov.b32 %bias_bits, %fBias;
    shfl.sync.idx.b32 %bias_bits_bcast, %bias_bits, 0, 0x1f, 0xffffffff;
    mov.b32 %fBias, %bias_bits_bcast;
    bra BIAS_PRELOAD_DONE;
BIAS_LOAD_WARP:
