    add.s32 %rBaseW, %rBaseW, %rCoRel;
    mul.lo.s32 %rBaseW, %rBaseW, %rKH;
    add.s32 %rBaseW, %rBaseW, %rKh;
    mul.lo.s32 %rBaseW, %rBaseW, %rKW;
