    mul.lo.s32 %rTmp6, %rCi, %rCoutPerG;
    add.s32 %rTmp6, %rTmp6, %rCoRelU;
    mul.lo.s32 %rTmp6, %rTmp6, %rKH;
    add.s32 %rTmp6, %rTmp6, %rNextKh;
    mul.lo.s32 %rTmp6, %rTmp6, %rKW;        // rTmp6 = baseWU(next)
