    @%p14 bra U_PREFETCHN_DONE;
    add.s32 %rTmp7, %rTmp6, %rLoadKwN;      // w_index next
    mul.wide.s32 %rd7, %rTmp7, 4;           // src bytes
    add.s64 %rd8, %rd2, %rd7;
    mul.wide.s32 %rd21, %rLoadKwN, 4;       // dst offset within buf
    add.s64 %rd22, %rd30, %rd21;            // dst ptr
    cp.async.ca.shared.global [%rd22], [%rd8], 4;
    add.s32 %rLoadKwN, %rLoadKwN, %ntid_x_s32;
