    mov.s32 %rKw, 0;
    // Precompute Tw0 and modular step
    add.s32 %rTw, %rWoIdx, %rPadW;
    rem.s32 %rDilWm, %rDilW, %rStrideW;
    rem.s32 %rRemW, %rTw, %rStrideW;
    setp.lt.s32 %p17, %rRemW, 0;
    @%p17 add.s32 %rRemW, %rRemW, %rStrideW;
    // select compute buffer base
    setp.eq.s32 %p27, %rBufSel, 0;
    @%p27 mov.u64 %rd31, %rd20;             // buf0
    @!%p27 add.s64 %rd31, %rd20, %rd33;      // buf1
U_KW_LOOP:
    setp.ge.s32 %p7, %rKw, %rKW;
    @%p7 bra U_AFTER_KW;
    // Iteration 0
    setp.ne.s32 %p8, %rRemW, 0;
    @%p8 bra U_KW_STEP1_DONE;
    div.s32 %rQw, %rTw, %rStrideW;
    setp.lt.s32 %p9, %rQw, 0;
    @%p9 bra U_KW_STEP1_DONE;
    setp.ge.s32 %p10, %rQw, %rW;
    @%p10 bra U_KW_STEP1_DONE;
