    add.s32 %rXIndex, %rBaseX, %rQw;
    // Load x and shared w
    mul.wide.s32 %rd5, %rXIndex, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];
    // Prepare vectorized shared load of w (maybe two)
    add.s32 %rKwNext, %rKw, 1;
    setp.lt.s32 %p19, %rKwNext, %rKW;
